fn try_chamfer_solid_along_wire_angle(
 solid:&Solid,wire:&Wire,reference:FaceID,distance:f64,angle:Rad<f64>,tol:f64,
)->std::result::Result<BlendResult,truck_base::diagnostics::Diagnostic>{
 let face=solid.face_iter().find(|f|f.id()==reference).unwrap();
 let edge=wire.front().unwrap();
 let found=face.edge_iter().find(|e|e.id()==edge.id()).unwrap();
 let side=usize::from(found.front()!=edge.front());
 let mut distances=[distance;2];distances[1-side]=distance*angle.0.tan();
 try_chamfer_solid_along_wire_chord(solid,wire,distances[0],distances[1],tol)
}
